<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { Activity, AlertTriangle, Building2, CircleDollarSign, Database, Gauge, RefreshCw, ServerCog, Sparkles, UsersRound } from "lucide-vue-next";
import { api, apiError } from "../services/api";
import { money } from "../services/format";
import type { AdminDashboard, AdminObservability } from "../types/api";

const summary = ref<AdminDashboard | null>(null), observability = ref<AdminObservability | null>(null), loading = ref(false), error = ref("");
const cards = computed(() => !summary.value ? [] : [
  { label: "Empresas registradas", value: summary.value.registeredTenants.toLocaleString("es-AR"), detail: "Negocios dados de alta", icon: Building2, tone: "pink" },
  { label: "Suscripciones activas", value: summary.value.activeSubscriptions.toLocaleString("es-AR"), detail: "Clientes con plan pago", icon: UsersRound, tone: "green" },
  { label: "Pruebas en curso", value: summary.value.trialingTenants.toLocaleString("es-AR"), detail: "Cuentas en período trial", icon: Sparkles, tone: "violet" },
  { label: "Facturación estimada del mes", value: money(summary.value.estimatedMonthlyRevenue), detail: "Estimación sobre planes activos", icon: CircleDollarSign, tone: "orange" },
]);
const formatBytes = (bytes: number) => {
  if (!bytes) return "0 MB";
  const units = ["B", "KB", "MB", "GB", "TB"];
  const index = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
  return `${new Intl.NumberFormat("es-AR", { maximumFractionDigits: 1 }).format(bytes / 1024 ** index)} ${units[index]}`;
};
const formatDateTime = (value: string) => new Date(value).toLocaleString("es-AR", { dateStyle: "short", timeStyle: "short" });
async function load() { loading.value = true; error.value = ""; try { const [dashboard, telemetry] = await Promise.all([api.get<AdminDashboard>("/admin/dashboard"), api.get<AdminObservability>("/admin/observability")]); summary.value = dashboard.data; observability.value = telemetry.data; } catch (cause) { error.value = apiError(cause); } finally { loading.value = false; } }
onMounted(load);
</script>

<template>
  <div class="page-heading"><div><div class="breadcrumb">SuperAdmin / Resumen</div><h1>Panel de control</h1><p>Visión global de empresas, suscripciones y facturación de la plataforma.</p></div><button class="secondary" :disabled="loading" @click="load"><RefreshCw :size="16" :class="{ spin: loading }" />Actualizar</button></div>
  <p v-if="error" class="error" role="alert">{{ error }}</p>
  <div v-else-if="loading && !summary" class="admin-kpis" aria-busy="true"><div v-for="i in 4" :key="i" class="admin-kpi skeleton"><div></div><div></div></div></div>
  <template v-else-if="summary && observability">
    <section class="admin-kpis"><article v-for="card in cards" :key="card.label" class="admin-kpi" :class="card.tone"><div class="admin-kpi-icon"><component :is="card.icon" :size="21" /></div><p>{{ card.label }}</p><strong>{{ card.value }}</strong><small>{{ card.detail }}</small></article></section>

    <section class="observability-heading"><div><div class="eyebrow"><Activity :size="15" />OPERACIÓN DE PLATAFORMA</div><h2>Salud, uso y crecimiento</h2><p>Datos globales de la base, las empresas y la API.</p></div><div class="database-chip"><Database :size="18" /><span>Base de datos</span><strong>{{ formatBytes(observability.databaseSizeBytes) }}</strong></div></section>

    <section class="data-counts"><article v-for="item in observability.dataCounts" :key="item.label"><span>{{ item.label }}</span><strong>{{ item.count.toLocaleString('es-AR') }}</strong></article></section>

    <section class="observability-grid">
      <article class="observability-panel tenant-usage"><header><div><h2><Building2 :size="18" />Uso por empresa</h2><p>Registros y volumen de ventas acumulados.</p></div><Gauge :size="20" /></header><div class="responsive-table"><table><thead><tr><th>Empresa</th><th>Productos</th><th>Clientes</th><th>Ventas</th><th>Comprobantes</th><th>Volumen</th></tr></thead><tbody><tr v-for="row in observability.tenantUsage" :key="row.tenantName"><td><strong>{{ row.tenantName }}</strong></td><td>{{ row.products }}</td><td>{{ row.customers }}</td><td>{{ row.sales }}</td><td>{{ row.invoices }}</td><td><strong>{{ money(row.salesVolume) }}</strong></td></tr><tr v-if="!observability.tenantUsage.length"><td colspan="6">Todavía no hay empresas con actividad registrada.</td></tr></tbody></table></div></article>
      <article class="observability-panel endpoint-usage"><header><div><h2><ServerCog :size="18" />Endpoints más solicitados</h2><p>Últimos siete días. Las rutas agrupan IDs internos.</p></div></header><div class="responsive-table"><table><thead><tr><th>Ruta</th><th>Llamados</th><th>Promedio</th><th>Fallos</th></tr></thead><tbody><tr v-for="endpoint in observability.topEndpoints" :key="`${endpoint.method}-${endpoint.path}`"><td><span class="method" :class="endpoint.method.toLowerCase()">{{ endpoint.method }}</span><code>{{ endpoint.path }}</code></td><td>{{ endpoint.requests.toLocaleString('es-AR') }}</td><td>{{ endpoint.averageDurationMs }} ms</td><td><span :class="endpoint.failedRequests ? 'status danger' : 'status success-status'">{{ endpoint.failedRequests }}</span></td></tr><tr v-if="!observability.topEndpoints.length"><td colspan="4">Las métricas aparecerán luego de recibir llamadas a la API.</td></tr></tbody></table></div></article>
    </section>

    <section class="observability-panel errors-panel"><header><div><h2><AlertTriangle :size="18" />Errores recientes del servidor</h2><p>Incluye fecha, ruta, empresa y usuario cuando estaban disponibles.</p></div></header><div class="responsive-table"><table><thead><tr><th>Fecha</th><th>Ruta</th><th>Empresa / usuario</th><th>Error</th></tr></thead><tbody><tr v-for="item in observability.recentErrors" :key="`${item.traceId}-${item.occurredAtUtc}`"><td>{{ formatDateTime(item.occurredAtUtc) }}</td><td><span class="status danger">{{ item.statusCode }}</span><code>{{ item.method }} {{ item.path }}</code></td><td><strong>{{ item.tenantName || 'Sin empresa' }}</strong><small>{{ item.userEmail || 'Usuario no identificado' }}</small></td><td><strong>{{ item.errorType }}</strong><small>{{ item.message }}</small></td></tr><tr v-if="!observability.recentErrors.length"><td colspan="4" class="empty-errors"><span><Activity :size="20" />Sin errores de servidor registrados.</span></td></tr></tbody></table></div></section>
  </template>
</template>

<style scoped>
.admin-kpis,.data-counts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}.admin-kpi{min-height:10rem;padding:1.2rem;border:1px solid #e2e8f0;border-top:3px solid #ec4899;border-radius:1rem;background:#fff}.admin-kpi.green{border-top-color:#10b981}.admin-kpi.violet{border-top-color:#8b5cf6}.admin-kpi.orange{border-top-color:#f97316}.admin-kpi-icon{display:grid;place-items:center;width:2.5rem;height:2.5rem;margin-bottom:1rem;border-radius:.7rem;background:#fdf2f8;color:#ec4899}.green .admin-kpi-icon{background:#ecfdf5;color:#059669}.violet .admin-kpi-icon{background:#f5f3ff;color:#7c3aed}.orange .admin-kpi-icon{background:#fff7ed;color:#ea580c}.admin-kpi p{margin:0;color:#64748b;font-size:.82rem}.admin-kpi strong{display:block;margin:.35rem 0 .55rem;color:#0f172a;font-size:1.75rem}.admin-kpi small{color:#94a3b8}.skeleton{min-height:10rem;background:linear-gradient(90deg,#f1f5f9,#fff,#f1f5f9);animation:pulse 1.4s infinite}@keyframes pulse{50%{opacity:.55}}.observability-heading{display:flex;align-items:end;justify-content:space-between;gap:1rem;margin:2.6rem 0 1rem}.eyebrow{display:flex;align-items:center;gap:.35rem;color:#be185d;font-size:.7rem;font-weight:800;letter-spacing:.1em}.observability-heading h2{margin:.35rem 0;color:#0f172a}.observability-heading p,.observability-panel header p{margin:0;color:#64748b}.database-chip{display:grid;grid-template-columns:auto auto;gap:.15rem .45rem;align-items:center;padding:.75rem 1rem;border:1px solid #f5d0e6;border-radius:.8rem;background:#fdf2f8;color:#9d174d;font-size:.75rem}.database-chip svg{grid-row:span 2}.database-chip strong{font-size:1.05rem}.data-counts{margin-bottom:1rem}.data-counts article{padding:1rem;border:1px solid #e2e8f0;border-radius:.8rem;background:#fff}.data-counts span{display:block;color:#64748b;font-size:.75rem}.data-counts strong{display:block;margin-top:.25rem;color:#0f172a;font-size:1.25rem}.observability-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:1rem;margin-bottom:1rem}.observability-panel{padding:1.15rem;border:1px solid #e2e8f0;border-radius:1rem;background:#fff}.observability-panel header{display:flex;align-items:start;justify-content:space-between;gap:1rem;margin-bottom:1rem}.observability-panel h2{display:flex;align-items:center;gap:.45rem;margin:0 0 .35rem;color:#0f172a;font-size:1rem}.observability-panel header>svg{color:#ec4899}.observability-panel td code{margin-left:.35rem;color:#475569;font-size:.72rem;white-space:nowrap}.method{display:inline-flex;min-width:2.9rem;justify-content:center;padding:.2rem .3rem;border-radius:.3rem;background:#e0f2fe;color:#0369a1;font-size:.65rem;font-weight:800}.method.post{background:#fce7f3;color:#be185d}.method.put,.method.delete{background:#fff7ed;color:#c2410c}.errors-panel td small,.errors-panel td strong{display:block}.errors-panel td small{margin-top:.2rem;color:#64748b}.empty-errors{padding:2rem!important;text-align:center;color:#047857}.empty-errors span{display:inline-flex;align-items:center;gap:.45rem}.dark .admin-kpi,.dark .data-counts article,.dark .observability-panel{border-color:#334155;background:#18233a}.dark .admin-kpi strong,.dark .data-counts strong,.dark .observability-heading h2,.dark .observability-panel h2{color:#f8fafc}.dark .admin-kpi p,.dark .observability-heading p,.dark .observability-panel header p,.dark .data-counts span,.dark .errors-panel td small{color:#b8c7dc}.dark .database-chip{border-color:#7c2d5b;background:#2e1930;color:#fbcfe8}.dark .observability-panel td code{color:#cbd5e1}@media(max-width:1100px){.observability-grid{grid-template-columns:1fr}.data-counts{grid-template-columns:repeat(2,1fr)}}@media(max-width:1000px){.admin-kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.admin-kpis,.data-counts{grid-template-columns:1fr}.observability-heading{align-items:stretch;flex-direction:column;margin-top:2rem}.database-chip{width:max-content}.observability-panel{padding:.85rem}.observability-panel td code{display:block;margin:.35rem 0 0;white-space:normal;overflow-wrap:anywhere}.admin-kpi{min-height:auto}}
</style>
